        sd0 = man(sx, sy, tx, ty)
        od1 = man(ox, oy, tx, ty)
        # Encourage getting closer to target and improving our deny margin vs opponent's reach.
        deny_now = (od1 - sd1)
        progress = sd0 - sd1
